public class BindingDemo {
    static class Animal {
        public static void staticMethod() {
            System.out.println("Animal static (Early Bound)");
        }
        public void dynamicMethod() {
            System.out.println("Animal instance (Late Bound)");
        }
    }

    static class Dog extends Animal {
        public static void staticMethod() {
            System.out.println("Dog static (Hides, not overrides)");
        }
        @Override
        public void dynamicMethod() {
            System.out.println("Dog instance (Polymorphic dispatch)");
        }
    }

    public static void main(String[] args) {
        Animal ref = new Dog();
        ref.staticMethod();  // Resolved via Animal (Static Binding)
        ref.dynamicMethod(); // Resolved via Dog (Dynamic Binding)
    }
}
